pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }
    function testFuzz_property(uint8 len, uint8 vSeed) public {
        vm.assume(len > 0);
        uint length = len;
        address[] memory tos = new address[](length);
        uint[] memory vs = new uint[](length);
        for (uint i = 0; i < length; i++) {
            tos[i] = address(uint160(uint(keccak256(abi.encode(vSeed, i)))));
            vs[i] = uint(keccak256(abi.encode(vSeed, i, len)));
        }
        address from = address(uint160(uint(keccak256(abi.encode("from", vSeed)))));
        address caddress = address(new Helper());
        bool ret = c.transfer(from, caddress, tos, vs);
        assertTrue(ret);
    }
}

contract Helper {
    fallback() external payable {}
}
